<?php
declare(strict_types=1);
require dirname(__DIR__).'/src/autoload.php';require __DIR__.'/BookingHarness.php';define('PREORDER_FIXTURE_ONLY',true);require __DIR__.'/preorders.php';define('POLICY_FIXTURE_ONLY',true);require __DIR__.'/policies.php';define('OPERATIONS_FIXTURE_ONLY',true);require __DIR__.'/operations.php';
function ocServer($t,string $tag='one'):array{$email='b6-claim-'.$tag.'@lumina.test';$q=$t->pdo->prepare('SELECT * FROM users WHERE email=?');$q->execute([$email]);$u=$q->fetch();if(!$u){$rid=(int)$t->pdo->query("SELECT id FROM roles WHERE code='server'")->fetchColumn();$t->pdo->prepare('INSERT INTO users(role_id,email,full_name,password_hash,is_active) VALUES (?,?,?,?,1)')->execute([$rid,$email,'B6 claim server',App\Service\StaffAuthService::password('Isolated claim verification 2026!')]);$q->execute([$email]);$u=$q->fetch();}return ['id'=>(int)$u['id'],'stamp'=>App\Core\StaffAccess::stamp($u)];}
function ocClaim($t,int $id,array $actor,string $action='claim'):array{$s=new App\Service\OrderService($t->pdo,new App\Service\BookingClock($t->pdo));$o=$s->detail($actor,$id);return $s->mutate($actor,$id,(int)$o['version'],$action,bin2hex(random_bytes(4)).'-1111-1111-1111-'.bin2hex(random_bytes(6)),[])['order'];}
$t->test('B6 server can claim auto-fired pre-order without firing food twice',function($t){$b=oBook($t);$id=oSeat($t,$b);$a=ocServer($t);$o=ocClaim($t,$id,$a);$t->assert((int)$o['assigned_server_id']===$a['id']&&$t->count('kitchen_tickets')===1&&$o['status']==='sent_to_kitchen');});
$t->test('B6 ready unassigned pre-order can be claimed served and closed',function($t){$b=oBook($t);$id=oSeat($t,$b);oAct($t,$id,'start');oAct($t,$id,'ready');$a=ocServer($t);ocClaim($t,$id,$a);ocClaim($t,$id,$a,'serve');$o=ocClaim($t,$id,$a,'close');$t->assert($o['status']==='closed'&&$t->count('billing_events')===0);$t->expectError('order_not_open',fn()=>ocClaim($t,$id,$a));});
$t->test('B6 live claim cannot steal another servers assignment',function($t){$b=oBook($t);$id=oSeat($t,$b);$a=ocServer($t);$other=ocServer($t,'two');ocClaim($t,$id,$a);$s=new App\Service\OrderService($t->pdo,new App\Service\BookingClock($t->pdo));$version=(int)$t->pdo->query('SELECT version FROM orders LIMIT 1')->fetchColumn();$t->expectError('order_forbidden',fn()=>$s->mutate($other,$id,$version,'claim','55555555-5555-5555-5555-555555555555',[]));});
$t->finish();
